{"file_path": "pytype/tests/test_methods.py", "original_signature": "def testAnnotatedSelf(self):", "target_file": {"ok": true, "path": "pytype/tests/test_methods.py", "sha": "052efe7e778cd0a0f7636581e7991f46c75587f1", "download_url": "https://raw.githubusercontent.com/google/pytype/3cf940d5066171dcf9bc42572cb48f9abb3883ac/pytype/tests/test_methods.py", "content_excerpt": "import unittest

from pytype import utils
from pytype.pytd import pytd
from pytype.tests import test_inference


class MethodsTest(test_inference.InferenceTest):

  def testFlowAndReplacementSanity(self):
    ty = self.Infer("""
      def f(x):
        if x:
          x = 42
          y = x
          x = 1
        return x + 4
      f(4)
    """, deep=False, show_library_calls=True)
    self.assertHasOnlySignatures(ty.Lookup("f"),
                                 ((self.int,), self.int))

  def testMultipleReturns(self):
    ty = self.Infer("""
      def f(x):
        if x:
          return 1
        else:
          return 1.5
      f(0)
      f(1)
    """, deep=False, show_library_calls=True)
    self.assertHasOnlySignatures(ty.Lookup("f"),
                                 ((self.int,), self.intorfloat))

  def testLoopsSanity(self):
    ty = self.Infer("""
      def f():
        x = 4
        y = -10
        for i in xrange(1000):
          x = x + (i+y)
          y = i
        return x
      f()
    """, deep=False, show_library_calls=True)
    self.assertHasOnlySignatures(ty.Lookup("f"), ((), self.int))

  def testAddInt(self):
    ty = self.Infer("""
      def f(x):
        return x + 1
      f(3.2)
      f(3)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.int)
    self.assertHasSignature(ty.Lookup("f"), (self.float,), self.float)

  def testAddFloat(self):
    ty = self.Infer("""
      def f(x):
        return x + 1.2
      f(3.2)
      f(3)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.intorfloat,), self.float)

  def testConjugate(self):
    ty = self.Infer("""
      def f(x, y):
        return x.conjugate()
      f(int(), int())
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int, self.int), self.int)

  def testClassSanity(self):
    ty = self.Infer("""
      class A(object):
        def __init__(self):
          self.x = 1

        def get_x(self):
          return self.x

        def set_x(self, x):
          self.x = x
      a = A()
      y = a.x
      x1 = a.get_x()
      a.set_x(1.2)
      x2 = a.get_x()
    """, deep=False)
    self.assertTypesMatchPytd(ty, """
      from typing import Union
      a = ...  # type: A
      x1 = ...  # type: int
      x2 = ...  # type: float
      y = ...  # type: int
      class A(object):
        x = ...  # type: float
        def get_x(self) -> Union[float, int]
        def set_x(self, x: float) -> None
    """)

  def testBooleanOp(self):
    ty = self.Infer("""
      def f(x, y):
        return 1 < x < 10
        return 1 > x > 10
      f(1, 2)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int, self.int), self.bool)

  def testIs(self):
    ty = self.Infer("""
      def f(a, b):
        return a is b
      f(1, 2)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int, self.int), self.bool)

  def testIsNot(self):
    ty = self.Infer("""
      def f(a, b):
        return a is not b
      f(1, 2)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int, self.int), self.bool)

  def testSlice(self):
    ty = self.Infer("""
      def f(x):
        a, b = x
        return (a, b)
      f((1, 2))
    """, deep=False, show_library_calls=True)
    t = pytd.TupleType(self.tuple, (self.int, self.int))
    self.assertHasSignature(ty.Lookup("f"), (t,), t)

  def testConvert(self):
    ty = self.Infer("""
      def f(x):
        return repr(x)
      f(1)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.str)

  def testNot(self):
    ty = self.Infer("""
      def f(x):
        return not x
      f(1)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.bool)

  def testPositive(self):
    ty = self.Infer("""
      def f(x):
        return +x
      f(1)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.int)

  def testNegative(self):
    ty = self.Infer("""
      def f(x):
        return -x
      f(1)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.int)

  def testInvert(self):
    ty = self.Infer("""
      def f(x):
        return ~x
      f(1)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.int)

  def testInheritance(self):
    ty = self.Infer("""
      class Base(object):
        def get_suffix(self):
            return u""

      class Leaf(Base):
        def __init__(self):
          pass

      def test():
        l1 = Leaf()
        return l1.get_suffix()

      if __name__ == "__main__":
        test()
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("test"), (), self.unicode)

  def testProperty(self):
    ty = self.Infer(
        """
      class A(object):
        @property
        def my_property(self):
          return 1
        def foo(self):
          return self.my_property

      def test():
        x = A()
        return x.foo()

      test()
    """, deep=False,
        show_library_calls=True, maximum_depth=4)
    self.assertHasSignature(ty.Lookup("test"), (), self.int)

  def testExplicitProperty(self):
    ty = self.Infer("""
      class B(object):
        def _my_getter(self):
          return 1
        def _my_setter(self):
          pass
        my_property = property(_my_getter, _my_setter)
      def test():
        b = B()
        b.my_property = 3
        return b.my_property
      test()
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("test"), (), self.int)

  def testInheritedProperty(self):
    self.assertNoErrors("""
      class A(object):
        @property
        def bar(self):
          return 42
      class B(A):
        def foo(self):
          return super(B, self).bar + 42
    """)

  def testGenerators(self):
    ty = self.Infer("""
      def f():
        yield 3
      def g():
        for x in f():
          return x
      g()
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (), self.generator)

  def testListGenerator(self):
    ty = self.Infer("""
      def f():
        yield 3
      def g():
        for x in list(f()):
          return x
      g()
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (), self.generator)

  def testRecursion(self):
    ty = self.Infer("""
      def f():
        if __random__:
          return f()
        else:
          return 3
      f()
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (), self.int)

  def testInNotIn(self):
    ty = self.Infer("""
      def f(x):
        if __random__:
          return x in [x]
        else:
          return x not in [x]

      f(3)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.bool)

  def testComplexCFG(self):
    ty = self.Infer("""
      def g(h):
        return 2
      def h():
        return 1
      def f(x):
        if x:
          while x:
            pass
          while x:
            pass
          assert x
        return g(h())
      if __name__ == "__main__":
        f(0)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.int)

  def testBranchAndLoopCFG(self):
    ty = self.Infer("""
      def g():
          pass
      def f():
          if True:
            while True:
              pass
            return False
          g()
      f()
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (), self.bool)

  def testClosure(self):
    ty = self.Infer("""
       def f(x, y):
         closure = lambda: x + y
         return closure()
       f(1, 2)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int, self.int), self.int)

  def testDeepClosure(self):
    ty = self.Infer("""
       def f():
         x = 3
         def g():
           def h():
             return x
           return h
         return g()()
       f()
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (), self.int)

  def testTwoClosures(self):
    ty = self.Infer("""
       def f():
         def g():
           return 3
         def h():
           return g
         return h()()
       f()
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (), self.int)

  def testClosureBindingArguments(self):
    ty = self.Infer("""
       def f(x):
         y = 1
         def g(z):
           return x + y + z
         return g(1)
       f(1)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.int)

  def testClosureOnMultiType(self):
    ty = self.Infer("""
      def f():
        if __random__:
          x = 1
        else:
          x = 3.5
        return (lambda: x)()
      f()
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (), self.intorfloat)

  def testCallKwArgs(self):
    ty = self.Infer("""
      def f(x, y=3):
        return x + y
      f(40, **{"y": 2})
    """, deep=False, show_library_calls=True)
    self.assertHasReturnType(ty.Lookup("f"), self.int)

  def testCallArgs(self):
    ty = self.Infer("""
      def f(x):
        return x
      args = (3,)
      f(*args)
    """, deep=False, show_library_calls=True)
    self.assertHasSignature(ty.Lookup("f"), (self.int,), self.int)

  def testCallArgsKwArgs(self):
    ty = self.Infer("""
      def f(x):
        return x
