    left = w_left._value
    right = w_right._value
    for i in range(min(len(left), len(right))):
        test = ord(left[i]) - ord(right[i])
        if test < 0:
            return space.wrap(-1)
        if test > 0:
            return space.wrap(1)

    test = len(left) - len(right)
    if test < 0:
        return space.wrap(-1)
    if test > 0:
        return space.wrap(1)
    return space.wrap(0)

