def _find(self, sub, start, end):
    if len(sub) == 0:
        return start
    if start >= end:
        return -1
    for i in range(start, end - len(sub) + 1):
        for j in range(len(sub)):
            if self[i + j]  != sub[j]:
                break
        else:
            return i
    return -1

def _rfind(self, sub, start, end):
    if len(sub) == 0:
        return end
    if end - start < len(sub):
        return -1
    for i in range(end - len(sub), start - 1, -1):
        for j in range(len(sub)):
            if self[i + j]  != sub[j]:
                break
        else:
            return i
    return -1

